body:
## What problem(s) does this PR solve?

Improves the performance of C#'s `Mathf.DegToRad`, `Mathf.RadToDeg`, and `Mathf.Lerp` functions by using the .NET methods `float.DegreesToRadians`, `float.RadiansToDegrees`, and `float.Lerp` (and the same for `double`).

Those methods use intrinsics, which seems to make them about 40% faster. They're already very fast, but these methods are used a lot, and `Mathf.Lerp` is also called by methods like `Vector3.Lerp`, so it may be worth doing.

This PR will result in a slight change of behaviour with extreme values. For example, the `float.DegreesToRadians` method multiplies first and divides second, which will slightly improve the precision with small values but slightly reduce the precision with massive values. I don't know if the .NET math functions need to exactly match the core C++ math functions.

Benchmarks (100 million iterations):
```
Godot DegToRad: 298.1016ms
.NET  DegToRad: 188.1239ms
Godot RadToDeg: 302.1955ms
.NET  RadToDeg: 188.4434ms
Godot Lerp: 337.4285ms
.NET  Lerp: 191.9934ms
```

<details>
<summary>See benchmarks source code</summary>

These benchmarks benchmark `double`. I did also benchmark `float` and got similar results.

```cs
using System.Diagnostics;

public class DegRadBench {
    public double Value = 0;

    public void BenchGodotDegToRad() {
        long s = Stopwatch.GetTimestamp();
        for (int i = 0; i < 100_000_000; i++) {
            Value = Mathf.DegToRad(35.3);
        }
        GD.Print("Godot DegToRad: " + Stopwatch.GetElapsedTime(s).TotalMilliseconds + "ms");
    }
    public void BenchDotNetDegToRad() {
        long s = Stopwatch.GetTimestamp();
        for (int i = 0; i < 100_000_000; i++) {
            Value = double.DegreesToRadians(35.3);
        }
        GD.Print(".NET  DegToRad: " + Stopwatch.GetElapsedTime(s).TotalMilliseconds + "ms");
    }
    public void BenchGodotRadToDeg() {
        long s = Stopwatch.GetTimestamp();
        for (int i = 0; i < 100_000_000; i++) {
            Value = Mathf.RadToDeg(35.3);
        }
        GD.Print("Godot RadToDeg: " + Stopwatch.GetElapsedTime(s).TotalMilliseconds + "ms");
    }
    public void BenchDotNetRadToDeg() {
        long s = Stopwatch.GetTimestamp();
        for (int i = 0; i < 100_000_000; i++) {
            Value = double.RadiansToDegrees(35.3);
        }
        GD.Print(".NET  RadToDeg: " + Stopwatch.GetElapsedTime(s).TotalMilliseconds + "ms");
    }
    public void BenchGodotLerp() {
        long s = Stopwatch.GetTimestamp();
        for (int i = 0; i < 100_000_000; i++) {
            Value = Mathf.Lerp(23.4, 96.2, 0.45);
        }
        GD.Print("Godot Lerp: " + Stopwatch.GetElapsedTime(s).TotalMilliseconds + "ms");
    }
    public void BenchDotNetLerp() {
        long s = Stopwatch.GetTimestamp();
        for (int i = 0; i < 100_000_000; i++) {
            Value = double.Lerp(23.4, 96.2, 0.45);
        }
        GD.Print(".NET  Lerp: " + Stopwatch.GetElapsedTime(s).TotalMilliseconds + "ms");
    }
}

public class DegRadBenchRunner {
    private readonly DegRadBench DegRadBench = new();

    public async void RunLoop() {
        while (true) {
            DegRadBench.BenchGodotDegToRad();
            DegRadBench.BenchDotNetDegToRad();
            DegRadBench.BenchGodotRadToDeg();
            DegRadBench.BenchDotNetRadToDeg();
            DegRadBench.BenchGodotLerp();
            DegRadBench.BenchDotNetLerp();
            GD.Print("----------");
            await Task.Delay(TimeSpan.FromSeconds(1.0));
        }
    }
}

```
</details>

## Additional information

See also #69490.

No AI used.
